  ) AS t(o, n) LOOP
    UPDATE public.posts SET content = replace(content, m.o, m.n) WHERE position(m.o in content) > 0;
    UPDATE public.pages SET content = replace(content, m.o, m.n) WHERE position(m.o in content) > 0;
  END LOOP;
END $$;

-- Kontrol: eski alan adına bakan görsel kalmamalı (ahajournals gibi dış kaynaklar hariç).
DO $$
DECLARE leftover int;
BEGIN
  SELECT count(*) INTO leftover FROM public.posts
   WHERE content LIKE '%aciltipuzmani.com/wp-content/uploads/%';
  RAISE NOTICE 'Eski uploads URL''i kalan yazi sayisi: %', leftover;
END $$;
